argv:
$ErrorActionPreference='Stop'
$target='E:\WebAIBridge-R68-OBSERVABILITY-20261014-GPT6'
$expected='f328f7b9deb517402a55374734be3d011dd9d0b7'
if(Test-Path -LiteralPath $target){throw 'R68_AUDIT_TARGET_EXISTS'}
& git.exe clone --quiet --depth 1 --single-branch --no-tags --branch agent/r68-live-chat-observability-20261014 https://github.com/foto6/WebAIBridge.git $target
if($LASTEXITCODE -ne 0){throw 'R68_CLONE_FAILED'}
$head=([string](& git.exe -C $target rev-parse HEAD)).Trim()
if($head -ne $expected){throw ('R68_EXACT_HEAD_DIFFERENT '+$head)}
$log=Join-Path $target 'R68_WINDOWS_TESTS.txt'
$uiLog=Join-Path $target 'R68_HTML_SYNTAX.txt'
Push-Location (Join-Path $target 'app')
try{
 & node.exe --check server.js *> $uiLog
 if($LASTEXITCODE -ne 0){throw 'SERVER_SYNTAX_FAIL'}
 $html=Get-Content -LiteralPath 'ui.html' -Raw
 $match=[regex]::Match($html,'(?s)<script>(.*?)</script>')
 if(-not $match.Success){throw 'UI_SCRIPT_NOT_FOUND'}
 $uiJs=Join-Path $target 'R68_ui_syntax.js'
 [System.IO.File]::WriteAllText($uiJs,$match.Groups[1].Value,[System.Text.UTF8Encoding]::new($false))
 & node.exe --check $uiJs *>> $uiLog
 if($LASTEXITCODE -ne 0){throw 'UI_SCRIPT_SYNTAX_FAIL'}
 & node.exe --test r68-live-chat-observability.test.js autonomous-send-gate-r50.test.js existing-tab-session-r55.test.js r65-global-canary-cap.test.js *> $log
 $rc=$LASTEXITCODE
 & node.exe ui-static.test.js *> (Join-Path $target 'R68_UI_STATIC_TEST.txt')
 $uiRc=$LASTEXITCODE
}finally{Pop-Location}
Write-Output ('EXACT_SHA='+$head)
Write-Output ('NODE_EXIT='+$rc)
Write-Output ('UI_STATIC_EXIT='+$uiRc)
Select-String -LiteralPath $log -Pattern '^ℹ (?:tests|pass|fail|skipped)|^✖'|Select-Object -Last 20|ForEach-Object {Write-Output $_.Line}
Write-Output ('UI_LOG='+$uiLog)
Write-Output ('PRODUCTION_HEAD='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
if($rc -ne 0 -or $uiRc -ne 0){throw 'R68_REGRESSION_FAILURE'}
